export type CapsuleContent = { error: string; log: string; once: { key: string; text: string } | null };
export function capsuleContent(): CapsuleContent;
export function subscribeCapsule(listener: () => void): () => void;
export function showOnce(key: string, text: () => string): void;
export function hideOnce(key: string): void;
export function dismissOnce(): void;
export function setStatus(msg: string, kind?: 'error'): void;
export function flash(msg: string): void;
export function setSummary(text: string): void;
export function renderError(error: string): void;
